const OOBE_STEPS_NON_DRIVER = 6;
const OOBE_STEPS_DRIVER = 7;
const AUTH_MEMBER_PORTAL_URL = "./index.html";
const AUTH_ADMIN_PORTAL_URL = "./admin.html";

// params: none
function createOobeDraft() {
    return {
        Federation_ID: "",
        Federation_Name: "",
        Accreditation_Number: "",
        Accreditation_Expiry: "",
        Office_Address: "",
        TODA_ID: "",
        TODA_Name: "",
        Route: "",
        SEC_Reg_Number: "",
        Terminal_Location: "",
        TODA_Accreditation_Expiry: "",
        Member_ID: "",
        First_Name: "",
        Last_Name: "",
        Street: "",
        Barangay: "",
        City_Municipality: DEFAULT_CITY_MUNICIPALITY,
        Contact_Number: "",
        isDriver: null,
        License_Number: "",
        License_Expiry_Date: "",
        License_Type: "Professional",
        Restriction_Code: "1",
        PSO_ID_Number: "",
        BLS_Cert_ID: ""
    };
}

// params: main (required), iconGlyph (optional), titleText (required), descText (optional)
function appendOobeStageHeader(main, iconGlyph, titleText, descText) {
    if (iconGlyph) {
        const icon = trIcon(iconGlyph, { size: "big", className: "as-centered" });
        main.appendChild(icon);
    }
    const headingWrap = trEl("div", "group vbox center space-t");
    const titleEl = trEl("p", "as-headline as-bold as-centered", titleText);
    headingWrap.appendChild(titleEl);
    if (descText) {
        const descEl = trEl("p", "as-secondary as-gray as-centered", descText);
        headingWrap.appendChild(descEl);
    }
    main.appendChild(headingWrap);
}

// params: draft (required), errorEl (required), submitBtn (required)
async function submitOobeDraft(draft, errorEl, submitBtn) {
    errorEl.classList.add("hidden");
    errorEl.textContent = "";
    submitBtn.disabled = true;
    submitBtn.classList.add("disabled");
    submitBtn.textContent = "Creating...";

    const payload = {
        Federation_ID: draft.Federation_ID,
        Federation_Name: draft.Federation_Name,
        Accreditation_Number: draft.Accreditation_Number,
        Accreditation_Expiry: draft.Accreditation_Expiry,
        Office_Address: draft.Office_Address,
        TODA_ID: draft.TODA_ID,
        TODA_Name: draft.TODA_Name,
        Route: draft.Route,
        SEC_Reg_Number: draft.SEC_Reg_Number,
        Terminal_Location: draft.Terminal_Location,
        TODA_Accreditation_Expiry: draft.TODA_Accreditation_Expiry,
        Association_Status: "Active",
        Member_ID: draft.Member_ID,
        First_Name: draft.First_Name,
        Last_Name: draft.Last_Name,
        Street: draft.Street,
        Barangay: draft.Barangay,
        City_Municipality: draft.City_Municipality,
        Contact_Number: draft.Contact_Number
    };

    if (draft.isDriver === true) {
        payload.License_Number = draft.License_Number;
        payload.License_Expiry_Date = draft.License_Expiry_Date || null;
        payload.License_Type = draft.License_Type || null;
        payload.Restriction_Code = draft.Restriction_Code || null;
        payload.PSO_ID_Number = draft.PSO_ID_Number || null;
        payload.BLS_Cert_ID = draft.BLS_Cert_ID || null;
    }

    try {
        await apiOobe(payload);
        setSessionMemberId(payload.Member_ID);

        const fullName = formatFullName(payload.First_Name, payload.Last_Name);
        const addressText = formatMemberAddress(payload);
        let licenseDisplay = "Non-driving member";
        if (payload.License_Number) {
            licenseDisplay = payload.License_Number;
        }
        const previewCard = trProfileCard({
            name: fullName,
            leftDetails: [addressText, payload.Contact_Number],
            rightDetails: [payload.TODA_Name, licenseDisplay]
        });

        presentSuccessScreen({
            title: "Setup complete",
            subtitle: payload.Federation_Name + " and " + payload.TODA_Name + " are ready.",
            card: previewCard,
            buttonLabel: "Open Dashboard",
            palette: "metal",
            onDone: function () {
                setRootPage(renderHomePage, { activeRole: "secretary" });
            }
        });
    } catch (err) {
        submitBtn.disabled = false;
        submitBtn.classList.remove("disabled");
        submitBtn.textContent = "Create federation & account";
        errorEl.textContent = err.message;
        errorEl.classList.remove("hidden");
    }
}

// params: params (optional: { step, draft })
function renderOobeStep(params) {
    const safeParams = params || {};
    const step = safeParams.step || 1;
    const draft = safeParams.draft || createOobeDraft();
    let totalSteps = OOBE_STEPS_NON_DRIVER;
    if (draft.isDriver === true) {
        totalSteps = OOBE_STEPS_DRIVER;
    }

    const output = [];
    const progressBar = trStoryBar({ total: totalSteps, current: step });
    output.push(progressBar);

    if (step > 1) {
        const navBar = trNavBar({ onBack: popPage });
        output.push(navBar);
    }

    const main = trEl("main", "content vbox justify-center space-xl flex1");
    const contentItems = [];
    const buttonItems = [];

    if (step === 1) {
        const welcomeWrap = trEl("div", "group vbox center space-t");
        const logo = trBrandLogo({ svg: TRIDE_AUTH_BRAND_SVG });
        const titleEl = trEl("p", "as-title as-bold as-centered");
        const line1 = document.createTextNode("Madali na lang");
        const br = document.createElement("br");
        const line2 = document.createTextNode("yan sa tride.");
        titleEl.appendChild(line1);
        titleEl.appendChild(br);
        titleEl.appendChild(line2);
        const desc = trEl("p", "as-secondary as-gray as-centered", "Set up your federation, founding TODA, and secretary profile.");
        trAppend(welcomeWrap, [logo, titleEl, desc]);
        main.appendChild(welcomeWrap);

        const startBtn = trButton({
            label: "Get started",
            variant: "primary",
            onClick: function () {
                pushPage(renderOobeStep, { step: 2, draft: draft });
            }
        });
        buttonItems.push(startBtn);

        if (typeof apiSeedSampleData === "function") {
            const seedBtn = trButton({
                label: "Load sample data",
                onClick: async function () {
                    seedBtn.disabled = true;
                    seedBtn.classList.add("disabled");
                    seedBtn.textContent = "Loading...";
                    try {
                        await apiSeedSampleData();
                        presentSuccessScreen({
                            title: "Sample data loaded",
                            subtitle: "Sign in with MEM-001 (Secretary/President), MEM-002 (Operator/Treasurer), or MEM-003 to MEM-006.",
                            buttonLabel: "Go to Login",
                            palette: "metal",
                            onDone: function () {
                                setRootPage(renderLoginPage, {});
                            }
                        });
                    } catch (err) {
                        seedBtn.disabled = false;
                        seedBtn.classList.remove("disabled");
                        seedBtn.textContent = "Load sample data";
                        trAlert({ title: "Error", message: err.message });
                    }
                }
            });
            buttonItems.push(seedBtn);
        }
    } else if (step === 2) {
        appendOobeStageHeader(main, null, "Federation setup", "Enter your federation details and city accreditation.");

        const fedIdRow = trPropertyRow({
            label: "Federation ID",
            input: { value: draft.Federation_ID, placeholder: "e.g. FED-01", maxLength: ID_MAX_LENGTH }
        });
        const fedNameRow = trPropertyRow({
            label: "Federation Name",
            input: { value: draft.Federation_Name, placeholder: "e.g. NCFETODA INC." }
        });
        const accredNoRow = trPropertyRow({
            label: "Accreditation Number",
            input: { value: draft.Accreditation_Number, placeholder: "e.g. SP-RES-2026-601" }
        });
        const accredExpRow = trPropertyRow({
            label: "Accreditation Expiry",
            input: { value: draft.Accreditation_Expiry, placeholder: "YYYY-MM-DD", maxLength: 10 }
        });
        const officeRow = trPropertyRow({
            label: "Office Address",
            input: { value: draft.Office_Address, placeholder: "e.g. Magsaysay Ave., Naga City" }
        });
        const fedCard = trListCard([fedIdRow, fedNameRow, accredNoRow, accredExpRow, officeRow]);
        contentItems.push(fedCard);

        const nextBtn = trButton({
            label: "Next",
            variant: "primary",
            onClick: function () {
                const fedId = fedIdRow.controlEl.value.trim();
                const fedName = fedNameRow.controlEl.value.trim();
                const accredNo = accredNoRow.controlEl.value.trim();
                const accredExp = accredExpRow.controlEl.value.trim();
                const office = officeRow.controlEl.value.trim();

                let valid = true;
                fedIdRow.setError("");
                fedNameRow.setError("");
                accredNoRow.setError("");
                accredExpRow.setError("");
                officeRow.setError("");

                if (!fedId) {
                    fedIdRow.setError("Enter a Federation ID.");
                    valid = false;
                }
                if (!fedName) {
                    fedNameRow.setError("Enter the federation name.");
                    valid = false;
                }
                if (!accredNo) {
                    accredNoRow.setError("Enter the accreditation number.");
                    valid = false;
                }
                if (!isValidIsoDate(accredExp)) {
                    accredExpRow.setError("Use YYYY-MM-DD date format.");
                    valid = false;
                }
                if (!office) {
                    officeRow.setError("Enter the federation office address.");
                    valid = false;
                }
                if (!valid) {
                    return;
                }

                draft.Federation_ID = fedId;
                draft.Federation_Name = fedName;
                draft.Accreditation_Number = accredNo;
                draft.Accreditation_Expiry = accredExp;
                draft.Office_Address = office;
                if (!draft.TODA_Accreditation_Expiry) {
                    draft.TODA_Accreditation_Expiry = accredExp;
                }
                pushPage(renderOobeStep, { step: 3, draft: draft });
            }
        });
        buttonItems.push(nextBtn);
    } else if (step === 3) {
        // based on final_dbms1_relational-model.md, MEMBER, register a founding TODA first because every member require a TODA_ID
        appendOobeStageHeader(main, null, "Founding TODA setup", "Every member belongs to a TODA. Register the first association.");

        const todaIdRow = trPropertyRow({
            label: "TODA ID",
            input: { value: draft.TODA_ID, placeholder: "e.g. TODA-01", maxLength: ID_MAX_LENGTH }
        });
        const todaNameRow = trPropertyRow({
            label: "TODA Name",
            input: { value: draft.TODA_Name, placeholder: "e.g. Mabolo TODA" }
        });
        const routeRow = trPropertyRow({
            label: "Route",
            input: { value: draft.Route, placeholder: "e.g. Mabolo - Centro" }
        });
        const secRegRow = trPropertyRow({
            label: "SEC Reg. Number",
            input: { value: draft.SEC_Reg_Number, placeholder: "e.g. SEC-CN202100101" }
        });
        const terminalRow = trPropertyRow({
            label: "Terminal Location",
            input: { value: draft.Terminal_Location, placeholder: "e.g. SM City Naga Terminal" }
        });
        const todaExpRow = trPropertyRow({
            label: "TODA Accreditation Expiry",
            input: { value: draft.TODA_Accreditation_Expiry, placeholder: "YYYY-MM-DD", maxLength: 10 }
        });
        const todaCard = trListCard([todaIdRow, todaNameRow, routeRow, secRegRow, terminalRow, todaExpRow]);
        contentItems.push(todaCard);

        const nextBtn = trButton({
            label: "Next",
            variant: "primary",
            onClick: function () {
                const todaId = todaIdRow.controlEl.value.trim();
                const todaName = todaNameRow.controlEl.value.trim();
                const route = routeRow.controlEl.value.trim();
                const secReg = secRegRow.controlEl.value.trim();
                const terminal = terminalRow.controlEl.value.trim();
                const todaExp = todaExpRow.controlEl.value.trim();

                let valid = true;
                todaIdRow.setError("");
                todaNameRow.setError("");
                routeRow.setError("");
                secRegRow.setError("");
                terminalRow.setError("");
                todaExpRow.setError("");

                if (!todaId) {
                    todaIdRow.setError("Enter a TODA ID.");
                    valid = false;
                }
                if (!todaName) {
                    todaNameRow.setError("Enter the TODA name.");
                    valid = false;
                }
                if (!route) {
                    routeRow.setError("Enter the TODA route.");
                    valid = false;
                }
                if (!secReg) {
                    secRegRow.setError("Enter the SEC registration number.");
                    valid = false;
                }
                if (!terminal) {
                    terminalRow.setError("Enter the terminal location.");
                    valid = false;
                }
                if (!isValidIsoDate(todaExp)) {
                    todaExpRow.setError("Use YYYY-MM-DD date format.");
                    valid = false;
                }
                if (!valid) {
                    return;
                }

                draft.TODA_ID = todaId;
                draft.TODA_Name = todaName;
                draft.Route = route;
                draft.SEC_Reg_Number = secReg;
                draft.Terminal_Location = terminal;
                draft.TODA_Accreditation_Expiry = todaExp;
                pushPage(renderOobeStep, { step: 4, draft: draft });
            }
        });
        buttonItems.push(nextBtn);
    } else if (step === 4) {
        appendOobeStageHeader(main, null, "Federation Secretary", "Create the first secretary account under " + draft.TODA_Name + ".");

        const secIdRow = trPropertyRow({
            label: "Member ID",
            input: { value: draft.Member_ID, placeholder: "e.g. MEM-001", maxLength: ID_MAX_LENGTH }
        });
        const firstRow = trPropertyRow({
            label: "First Name",
            input: { value: draft.First_Name, placeholder: "First name" }
        });
        const lastRow = trPropertyRow({
            label: "Last Name",
            input: { value: draft.Last_Name, placeholder: "Last name" }
        });
        const streetRow = trPropertyRow({
            label: "Street",
            input: { value: draft.Street, placeholder: "e.g. 12 Rizal St." }
        });
        const brgyRow = trPropertyRow({
            label: "Barangay",
            input: { value: draft.Barangay, placeholder: "e.g. Mabolo" }
        });
        const cityRow = trPropertyRow({
            label: "City / Municipality",
            input: { value: draft.City_Municipality, placeholder: "e.g. Naga City" }
        });
        const contactRow = trPropertyRow({
            label: "Contact Number",
            input: { value: draft.Contact_Number, placeholder: "09XXXXXXXXX" }
        });
        const secCard = trListCard([secIdRow, firstRow, lastRow, streetRow, brgyRow, cityRow, contactRow]);
        contentItems.push(secCard);

        const nextBtn = trButton({
            label: "Next",
            variant: "primary",
            onClick: function () {
                const secId = secIdRow.controlEl.value.trim();
                const firstName = firstRow.controlEl.value.trim();
                const lastName = lastRow.controlEl.value.trim();
                const street = streetRow.controlEl.value.trim();
                const barangay = brgyRow.controlEl.value.trim();
                const city = cityRow.controlEl.value.trim();
                const contact = contactRow.controlEl.value.trim();

                let valid = true;
                secIdRow.setError("");
                firstRow.setError("");
                lastRow.setError("");
                streetRow.setError("");
                brgyRow.setError("");
                cityRow.setError("");
                contactRow.setError("");

                if (!secId) {
                    secIdRow.setError("Enter a Member ID.");
                    valid = false;
                }
                if (!firstName) {
                    firstRow.setError("Enter a first name.");
                    valid = false;
                }
                if (!lastName) {
                    lastRow.setError("Enter a last name.");
                    valid = false;
                }
                if (!street) {
                    streetRow.setError("Enter a street address.");
                    valid = false;
                }
                if (!barangay) {
                    brgyRow.setError("Enter a barangay.");
                    valid = false;
                }
                if (!city) {
                    cityRow.setError("Enter a city or municipality.");
                    valid = false;
                }
                if (!contact) {
                    contactRow.setError("Enter a contact number.");
                    valid = false;
                }
                if (!valid) {
                    return;
                }

                draft.Member_ID = secId;
                draft.First_Name = firstName;
                draft.Last_Name = lastName;
                draft.Street = street;
                draft.Barangay = barangay;
                draft.City_Municipality = city;
                draft.Contact_Number = contact;
                pushPage(renderOobeStep, { step: 5, draft: draft });
            }
        });
        buttonItems.push(nextBtn);
    } else if (step === 5) {
        appendOobeStageHeader(main, null, "Are you a driver?", "Choose whether to add driver license and safety credentials.");

        const errorEl = trEl("p", "as-secondary as-critical as-centered hidden", "");
        let initialVal = null;
        if (draft.isDriver === true) {
            initialVal = "yes";
        } else if (draft.isDriver === false) {
            initialVal = "no";
        }

        const driverRadio = trRadioGroup({
            name: "oobe-driver-choice",
            label: "Driver status",
            value: initialVal,
            items: [
                { value: "yes", title: "I am a driver", subtitle: "Add license, PSO ID, and BLS details next." },
                { value: "no", title: "I am not a driver", subtitle: "Leave driver credential fields blank." }
            ],
            onChange: function (val) {
                draft.isDriver = val === "yes";
                errorEl.classList.add("hidden");
            }
        });
        contentItems.push(driverRadio, errorEl);

        const nextBtn = trButton({
            label: "Next",
            variant: "primary",
            onClick: function () {
                const chosen = driverRadio.getValue();
                if (!chosen) {
                    errorEl.textContent = "Please choose one option.";
                    errorEl.classList.remove("hidden");
                    return;
                }
                if (chosen === "yes") {
                    draft.isDriver = true;
                    pushPage(renderOobeStep, { step: 6, draft: draft });
                    return;
                }
                draft.isDriver = false;
                draft.License_Number = "";
                draft.License_Expiry_Date = "";
                draft.License_Type = "";
                draft.Restriction_Code = "";
                draft.PSO_ID_Number = "";
                draft.BLS_Cert_ID = "";
                pushPage(renderOobeStep, { step: 6, draft: draft });
            }
        });
        buttonItems.push(nextBtn);
    } else if (step === 6 && draft.isDriver === true) {
        appendOobeStageHeader(main, null, "Driver credentials", "Enter your driver license and Naga City safety IDs.");

        const licRow = trPropertyRow({
            label: "License Number",
            input: { value: draft.License_Number, placeholder: "e.g. E01-19-001122" }
        });
        const licExpRow = trPropertyRow({
            label: "License Expiry Date",
            input: { value: draft.License_Expiry_Date, placeholder: "YYYY-MM-DD", maxLength: 10 }
        });
        const licTypeOptions = buildSelectOptions(LICENSE_TYPES, "Select license type");
        const licTypeRow = trPropertyRow({
            label: "License Type",
            select: { value: draft.License_Type || "Professional", options: licTypeOptions }
        });
        const restRow = trPropertyRow({
            label: "Restriction Code",
            input: { value: draft.Restriction_Code, placeholder: "e.g. 1", maxLength: 10 }
        });
        const psoRow = trPropertyRow({
            label: "PSO ID Number",
            input: { value: draft.PSO_ID_Number, placeholder: "e.g. PSO-2026-001" }
        });
        const blsRow = trPropertyRow({
            label: "BLS Cert ID",
            input: { value: draft.BLS_Cert_ID, placeholder: "e.g. BLS-2026-001" }
        });
        const credCard = trListCard([licRow, licExpRow, licTypeRow, restRow, psoRow, blsRow]);
        contentItems.push(credCard);

        const nextBtn = trButton({
            label: "Review & finish",
            variant: "primary",
            onClick: function () {
                const licNum = licRow.controlEl.value.trim();
                const licExp = licExpRow.controlEl.value.trim();
                const licType = licTypeRow.controlEl.value;
                const restCode = restRow.controlEl.value.trim();
                const psoId = psoRow.controlEl.value.trim();
                const blsId = blsRow.controlEl.value.trim();

                let valid = true;
                licRow.setError("");
                licExpRow.setError("");

                if (!licNum) {
                    licRow.setError("Enter your driver's license number.");
                    valid = false;
                }
                if (licExp && !isValidIsoDate(licExp)) {
                    licExpRow.setError("Use YYYY-MM-DD date format.");
                    valid = false;
                }
                if (!valid) {
                    return;
                }

                draft.License_Number = licNum;
                draft.License_Expiry_Date = licExp;
                draft.License_Type = licType;
                draft.Restriction_Code = restCode;
                draft.PSO_ID_Number = psoId;
                draft.BLS_Cert_ID = blsId;
                pushPage(renderOobeStep, { step: 7, draft: draft });
            }
        });
        buttonItems.push(nextBtn);
    } else {
        appendOobeStageHeader(main, "\uE73E", "Review setup", "Check your federation, founding TODA, and secretary details.");

        const fullName = formatFullName(draft.First_Name, draft.Last_Name);
        const addressText = formatMemberAddress(draft);
        let licenseDisplay = "Not a driver";
        if (draft.isDriver === true && draft.License_Number) {
            licenseDisplay = draft.License_Number;
            if (draft.License_Type) {
                licenseDisplay = licenseDisplay + " (" + draft.License_Type + ")";
            }
        }

        const reviewRows = [
            trPropertyRow({ label: "Federation", value: draft.Federation_Name + " (" + draft.Federation_ID + ")" }),
            trPropertyRow({ label: "Accreditation", value: draft.Accreditation_Number + " · exp " + draft.Accreditation_Expiry }),
            trPropertyRow({ label: "Founding TODA", value: draft.TODA_Name + " (" + draft.TODA_ID + ")" }),
            trPropertyRow({ label: "Route & Terminal", value: draft.Route + " · " + draft.Terminal_Location }),
            trPropertyRow({ label: "Secretary", value: fullName + " (" + draft.Member_ID + ")" }),
            trPropertyRow({ label: "Address", value: addressText }),
            trPropertyRow({ label: "Contact", value: draft.Contact_Number }),
            trPropertyRow({ label: "Driver License", value: licenseDisplay })
        ];
        const reviewCard = trListCard(reviewRows);
        const errorEl = trEl("p", "as-secondary as-critical as-centered hidden", "");
        contentItems.push(reviewCard, errorEl);

        const submitBtn = trButton({
            label: "Create federation & account",
            variant: "primary",
            onClick: function () {
                submitOobeDraft(draft, errorEl, submitBtn);
            }
        });
        buttonItems.push(submitBtn);
    }

    if (contentItems.length > 0) {
        const contentWrap = trEl("div", "group vbox space-l");
        trAppend(contentWrap, contentItems);
        main.appendChild(contentWrap);
    }
    if (buttonItems.length > 0) {
        const actionsWrap = trEl("div", "group vbox space-l");
        trAppend(actionsWrap, buttonItems);
        main.appendChild(actionsWrap);
    }
    output.push(main);
    return output;
}

// params: params (optional: { draft })
function renderOobePage(params) {
    const safeParams = params || {};
    if (!safeParams.draft) {
        safeParams.draft = createOobeDraft();
    }
    return renderOobeStep({ step: 1, draft: safeParams.draft });
}

// params: none
function renderLoginPage() {
    const main = trEl("main", "content vbox justify-center space-xl flex1");
    const isAdminPortal = window.location.pathname.indexOf("admin") !== -1;
    let portalType = "member";
    let heroHeading = "Madali na lang yan\nsa tride.";
    if (isAdminPortal) {
        portalType = "admin";
        heroHeading = "Ready for takeoff.";
    }

    const hero = trEl("div", "group vbox center space-t");
    const brandLogo = trBrandLogo({ svg: TRIDE_AUTH_BRAND_SVG });
    hero.appendChild(brandLogo);
    const heroTitle = trEl("p", "as-title as-bold as-centered");
    const heroLines = heroHeading.split("\n");
    for (let i = 0; i < heroLines.length; i += 1) {
        if (i > 0) {
            const br = document.createElement("br");
            heroTitle.appendChild(br);
        }
        const lineNode = document.createTextNode(heroLines[i]);
        heroTitle.appendChild(lineNode);
    }
    hero.appendChild(heroTitle);

    const idRow = trPropertyRow({
        label: "Member ID",
        input: { placeholder: "e.g. MEM-001", maxLength: ID_MAX_LENGTH }
    });
    const loginCardInner = trCard([idRow]);
    const loginCard = trCardGroup({
        card: loginCardInner,
        footnote: "Use the Member ID issued by your TODA or federation."
    });

    async function handleLoginSubmit() {
        const memberId = idRow.controlEl.value.trim();
        if (!memberId) {
            idRow.setError("Please enter your Member ID.");
            return;
        }

        loginBtn.disabled = true;
        loginBtn.classList.add("disabled");
        loginBtn.textContent = "Signing in...";

        try {
            const res = await apiLogin(memberId, portalType);
            idRow.setError("");
            setSessionMemberId(res.member.Member_ID);
            setRootPage(renderHomePage, { activeRole: null });
        } catch (err) {
            loginBtn.disabled = false;
            loginBtn.classList.remove("disabled");
            loginBtn.textContent = "Log in";
            idRow.setError(err.message);
        }
    }

    if (idRow.controlEl) {
        idRow.controlEl.addEventListener("keydown", function (event) {
            if (event.key === "Enter") {
                handleLoginSubmit();
            }
        });
    }

    const loginBtn = trButton({
        label: "Log in",
        variant: "primary",
        onClick: handleLoginSubmit
    });

    let footerNote = "TODA Officer or Federation Secretary?";
    let footerBtnLabel = "Sign in at Admin Portal";
    let footerTarget = AUTH_ADMIN_PORTAL_URL;
    if (isAdminPortal) {
        footerNote = "Driver or Operator?";
        footerBtnLabel = "Back to Member App";
        footerTarget = AUTH_MEMBER_PORTAL_URL;
    }

    const footerCaption = trEl("p", "as-tertiary as-centered as-gray", footerNote);
    const footerBtn = trButton({
        label: footerBtnLabel,
        onClick: function () {
            window.location.href = footerTarget;
        }
    });

    const contentWrap = trEl("div", "group vbox space-l");
    trAppend(contentWrap, [loginCard, loginBtn]);

    const footerWrap = trEl("div", "group vbox space-m");
    trAppend(footerWrap, [footerCaption, footerBtn]);

    trAppend(main, [hero, contentWrap, footerWrap]);
    return [main];
}
